#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
namespace StarterAssets.CQCEditorTools {
[InitializeOnLoad] public static class RebuildCleanChapelTeleport {
const string Request="Assets/Editor/CQC/RebuildCleanChapelTeleport-v1.request.txt";static double next;
static RebuildCleanChapelTeleport(){EditorApplication.update+=Poll;}
static void Poll(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+2;if(!File.Exists(Request)||EditorApplication.isCompiling||EditorApplication.isUpdating)return;if(EditorApplication.isPlaying){EditorApplication.ExitPlaymode();return;}if(EditorApplication.isPlayingOrWillChangePlaymode)return;Undo.IncrementCurrentGroup();int group=Undo.GetCurrentGroup();try{Apply();Undo.CollapseUndoOperations(group);AssetDatabase.DeleteAsset(Request);}catch(Exception e){Undo.RevertAllDownToGroup(group);File.WriteAllText("Logs/CleanChapelTeleport-error.txt",e.ToString());Debug.LogException(e);AssetDatabase.MoveAsset(Request,Request+".failed");}}
static Transform Anchor(Transform parent,string name,Vector3 p,Quaternion rotation){var g=new GameObject(name);Undo.RegisterCreatedObjectUndo(g,"Rebuild chapel teleport");g.transform.SetParent(parent,true);g.transform.SetPositionAndRotation(p,rotation);return g.transform;}
static bool Clear(Vector3 p,CharacterController cc){float r=cc.radius*.95f;return Physics.OverlapCapsule(p+Vector3.up*(r+.12f),p+Vector3.up*(cc.height-r),r,~0,QueryTriggerInteraction.Ignore).All(c=>c.transform.IsChildOf(cc.transform));}
static void Apply(){var original=SceneManager.GetActiveScene();var main=SceneManager.GetSceneByPath("Assets/Scenes/MyForest.unity");bool openedMain=!main.isLoaded;if(openedMain)main=EditorSceneManager.OpenScene("Assets/Scenes/MyForest.unity",OpenSceneMode.Additive);var domain=SceneManager.GetSceneByPath(ChapelThroneDomain.ScenePath);bool openedDomain=!domain.isLoaded;if(openedDomain)domain=EditorSceneManager.OpenScene(ChapelThroneDomain.ScenePath,OpenSceneMode.Additive);
try{SceneManager.SetActiveScene(main);var mountain=main.GetRootGameObjects().First(g=>g.name=="Castle Mountain");var church=mountain.transform.Find("Large Upper Castle Church");var player=main.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<StarterAssets.ThirdPersonController>(true)).First().transform;var cc=player.GetComponent<CharacterController>();var floor=mountain.transform.Find("Inner Castle Mountain/Flat Inner Castle Floor").GetComponent<MeshCollider>();var room=domain.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<ThroneDomainRoom>(true)).Single();Physics.SyncTransforms();
string stamp=DateTime.Now.ToString("yyyyMMdd-HHmmss"),backup="Assets/ForestExpansion/Backups/";if(!EditorSceneManager.SaveScene(main,backup+"MyForest-before-clean-chapel-"+stamp+".unity",true)||!EditorSceneManager.SaveScene(domain,backup+"ThroneDomain-before-clean-teleport-"+stamp+".unity",true))throw new IOException("Scene backup failed.");
var models=mountain.GetComponentsInChildren<Transform>(true);var matrices=models.Select(t=>t.localToWorldMatrix).ToArray();var front=Vector3.ProjectOnPlane(-church.forward,Vector3.up).normalized;var center=church.position;center.y=floor.bounds.max.y;var origin=center+front*100+Vector3.up*1.4f;float nearest=200;Vector3 surface=Vector3.zero;bool found=false;foreach(var c in church.GetComponentsInChildren<Collider>())if(c.Raycast(new Ray(origin,-front),out var h,200)&&h.distance<nearest){surface=h.point;nearest=h.distance;found=true;}if(!found)throw new InvalidOperationException("Main chapel door surface is missing.");var entry=surface+front*.65f;entry.y=center.y+.06f;var back=entry+front*3.2f;if(!floor.Raycast(new Ray(back+Vector3.up*5,Vector3.down),out var ground,10))throw new InvalidOperationException("Courtyard support is missing.");back.y=ground.point.y+.06f;if(!Clear(back,cc))throw new InvalidOperationException("Courtyard return is blocked.");
var arrival=room.Arrival?room.Arrival.position:room.transform.position+new Vector3(0,.06f,32.3f);var facing=room.Arrival?room.Arrival.rotation:Quaternion.Euler(0,180,0);var exit=room.ReturnDoor?room.ReturnDoor.position:room.transform.position+new Vector3(0,.06f,35.5f);if(!Clear(arrival,cc))throw new InvalidOperationException("Room arrival is blocked.");
int removed=0;foreach(var portal in main.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<ChapelThroneDomain>(true)).ToArray()){if(portal.transform.parent==null&&portal.name.Contains("Chapel")){Undo.DestroyObjectImmediate(portal.gameObject);removed++;}else{Undo.DestroyObjectImmediate(portal);removed++;}}
foreach(var old in main.GetRootGameObjects().Where(g=>g.name.StartsWith("Chapel Throne Domain Entrance")).ToArray())Undo.DestroyObjectImmediate(old);
SceneManager.SetActiveScene(main);var root=new GameObject("Chapel Throne Domain Entrance");Undo.RegisterCreatedObjectUndo(root,"Rebuild clean chapel teleport");var fresh=root.AddComponent<ChapelThroneDomain>();fresh.Player=player;fresh.ChapelDoor=Anchor(root.transform,"Chapel Main Door Interaction",entry,Quaternion.LookRotation(front));fresh.OutsideReturn=Anchor(root.transform,"Safe Courtyard Return",back,Quaternion.LookRotation(front));fresh.BackDoor=null;fresh.BackOutsideReturn=null;fresh.InteractionRange=5;
Undo.RecordObject(room,"Rebuild room arrival and exit");foreach(var old in room.transform.Cast<Transform>().Where(t=>t==room.Arrival||t==room.ReturnDoor||t.name=="Throne Hall Arrival"||t.name=="Return To Chapel Door").ToArray())Undo.DestroyObjectImmediate(old.gameObject);
SceneManager.SetActiveScene(domain);room.Arrival=Anchor(room.transform,"Throne Hall Arrival",arrival,facing);room.ReturnDoor=Anchor(room.transform,"Return To Chapel Door",exit,facing);
for(int i=0;i<models.Length;i++)if(models[i].localToWorldMatrix!=matrices[i])throw new InvalidOperationException("An existing castle model moved.");
if(fresh.BackDoor||fresh.BackOutsideReturn||main.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<ChapelThroneDomain>(true)).Count()!=1)throw new InvalidOperationException("Duplicate entrance remains.");EditorSceneManager.MarkSceneDirty(main);EditorSceneManager.MarkSceneDirty(domain);if(!EditorSceneManager.SaveScene(main)||!EditorSceneManager.SaveScene(domain))throw new IOException("Scene save failed.");
File.WriteAllText("Logs/CleanChapelTeleport-report.txt","PASS: Removed "+removed+" old portal controller(s), their front/back markers and added rear-door geometry. Created one clean main chapel entrance, one safe courtyard return, and fresh throne-room arrival/exit anchors. Existing throne room, queen, city and castle transforms preserved.\nEntrance: "+entry+"\nCourtyard return: "+back+"\nArrival: "+arrival+"\nExit: "+exit+"\nBackup stamp: "+stamp);File.WriteAllText("Assets/Editor/CQC/TestChapelThroneTravel-clean.request.txt","Verify the clean original-style main-door entrance and room exit.");Debug.Log("Clean chapel entrance and throne-room return rebuilt and saved.");
}finally{if(original.IsValid()&&original.isLoaded)SceneManager.SetActiveScene(original);if(openedDomain)EditorSceneManager.CloseScene(domain,true);if(openedMain)EditorSceneManager.CloseScene(main,true);}}
}}
#endif
